// DRY: Centralizing validation logic instead of repeating it in every service method
public class Validator {
    public static <T> void validateNotNull(T object, String fieldName) {
        if (object == null) {
            throw new IllegalArgumentException(fieldName + " cannot be null");
        }
    }
}

// KISS/YAGNI: Avoid creating a complex 'UserFactory' interface if a simple constructor suffices
public class User {
    private final String name;
    public User(String name) {
        this.name = name;
    }
}
